function campusRoute(from,to){
 if(Math.hypot(from[0]-to[0],from[1]-to[1])<.01)return[];
 const hub=[0,-6];
 function exit(q){const [x,z]=q;
  if(Math.abs(x)<7&&z>=14){const edge=x<0?-3.6:3.6;return[[...q],[edge,z],[edge,15.2],[0,15.2],[0,13.1],[7.8,13.1],[7.8,-6],hub]}
  if(x>=-8&&x<=-2&&z<-16.5)return[[...q],[-5,z],[-5,-16],[-7.8,-16],[-7.8,-6],hub];
  if(Math.abs(x)<4.7&&z<-9)return[[...q],[0,z],[0,-18.3],[7.8,-18.3],[7.8,-6],hub];
  if(Math.abs(x)<7&&z>=0&&z<=12)return[[...q],[2.7,z],[2.7,1],[0,1],[0,-.8],hub];
  if(Math.abs(x)>8.5){const side=Math.sign(x),doorZ=z>13?16.6:people.filter(p=>Math.sign(p.home[0])===side&&p.home[0]!==0).sort((a,b)=>Math.abs(a.home[1]-z)-Math.abs(b.home[1]-z))[0].home[1];return[[...q],[x,doorZ],[side*7.8,doorZ],[side*7.8,-6],hub]}
  if(Math.abs(x)>4.7)return[[...q],[Math.sign(x)*7.8,z],[Math.sign(x)*7.8,-6],hub];
  return[[...q],[x,-6],hub];
 }
 const points=[...exit(from),...exit(to).reverse()];const result=[];let prev=from;for(const q of points){if(Math.hypot(q[0]-prev[0],q[1]-prev[1])>.01){result.push([...q]);prev=q}}return result;
}
const trafficObstacles=[];
function trafficRoom(x,z,w,d,doorSide,doorAt){for(const side of ['north','south','west','east']){const h=side==='north'||side==='south',fixed=h?z+(side==='north'?-d/2:d/2):x+(side==='west'?-w/2:w/2),lo=h?x-w/2:z-d/2,hi=h?x+w/2:z+d/2;for(const[a,b]of(side===doorSide?[[lo,doorAt-1.35],[doorAt+1.35,hi]]:[[lo,hi]]))if(b>a)trafficObstacles.push({x:h?(a+b)/2:fixed,z:h?fixed:(a+b)/2,w:h?b-a:.13,d:h?.13:b-a})}}
people.forEach(p=>trafficRoom(p.home[0],p.home[1]+1,9,8,p.home[0]===0?'north':p.home[0]<0?'east':'west',p.home[0]===0?0:p.home[1]));trafficRoom(0,6,14,12,'north',0);trafficRoom(13,18,9,8,'west',16.6);trafficRoom(-13,18,9,8,'east',16.6);trafficRoom(-5,-19,6,5,'south',-5);trafficRoom(0,18,14,8,'north',0);
people.forEach(p=>trafficObstacles.push({x:p.home[0],z:p.home[1]+1,w:3,d:1.15}));trafficObstacles.push({x:0,z:8,w:3.5,d:1.15},{x:0,z:18,w:5.4,d:2.1},{x:13,z:17.7,w:4.3,d:1.7},{x:-13,z:18.3,w:2.8,d:1.25});
trafficObstacles.push(...[...ceoFurniture,...ceoWallDecor].map(f=>({id:'ceo-'+f.id,x:f.x,z:f.z,w:f.w+.12,d:f.d+.12})));
trafficObstacles.push(...studioFloorHoles);
const traffic=createStudioTraffic(trafficObstacles);let directorActor=null;
const building=createStudioBuilding(people,traffic,()=>directorActor);
function route(p,target,cb,afterKind){p.mode='walking';p.timer=0;p.route=campusRoute(p.pos,target);p.after=cb;p.afterKind=afterKind||null;traffic.request(p);render()}

function setMode(p,m,seconds=0){p.mode=m;p.timer=seconds;render()}
function announce(s){$('scene-status').textContent=s;log(s);render()}
function choosePlan(text){
 const s=text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const full=/(crear|crea|desarroll|constru|implement|hacer|quiero|proyecto).*(sistema|aplicacion|app\b|software|plataforma|inventario|web|proyecto)/.test(s)||/sistema de |aplicacion de |proyecto de software/.test(s);
 const bug=/error|bug|fallo|corrige|corregir|depur|arregla/.test(s),db=/base de datos|sql|consulta|tablas|entidad|datos|persistencia/.test(s);
 const arch=/arquitectura|arquitecto|componentes|estructura del sistema|diseno tecnico/.test(s);
 const req=/requisito|historias de usuario|casos de uso|investig|busca|compar|analiz|informacion|idea/.test(s);
 const doc=/document|manual|presenta|ppt|informe|redact|escrib|propuesta/.test(s);
 const dev=/program|codigo|implement|funcion|api|backend|frontend|desarroll/.test(s),qa=/prueba|test|calidad|validar|verific/.test(s);
 const chosen=new Set();if(full){[1,3,5,4,6,2].forEach(i=>chosen.add(i))}else{
 if(req)chosen.add(1);if(arch)chosen.add(3);if(db)chosen.add(5);if(dev||bug)chosen.add(4);if(qa||dev||bug||db)chosen.add(6);if(doc)chosen.add(2);
 }
 const titles={0:'Organizar el plan del proyecto',1:'Definir requisitos y criterios de aceptación',3:'Diseñar la arquitectura del sistema',5:'Diseñar el modelo de datos',4:bug?'Diagnosticar y corregir el error':'Implementar las funciones del sistema',6:'Preparar pruebas y verificar requisitos',2:'Documentar la entrega técnica'};
 const ids=[1,3,5,4,6,2].filter(i=>chosen.has(i));if(!ids.length)ids.push(0);
 return ids.map(agent=>({agent,title:titles[agent],status:'Pendiente'}));
}
function send(text,i=0){const t={id:crypto.randomUUID(),text,agent:0,orchestrated:true,status:'En cola',steps:choosePlan(text),cursor:0};data.tasks.push(t);missions.push(t);data.messages[0].push({user:true,text},{text:'Recibí tu misión. Yo organizaré los encargos y te presentaré la entrega. Esta es una simulación por reglas, todavía sin IA.'});if(i!==0)data.messages[i].push({user:true,text},{text:'Pasé tu misión a Nico para que organice al equipo.'});announce('Nueva misión para Nico: '+text);startMission();toast(mission===t?'Nico viene a recibir tu orden.':'Misión en cola. Nico la recibirá al terminar la actual.')}
function startMission(){const p=people[0];if(mission||!missions.length)return;if(building.hasVisitors()){building.recall();$('scene-status').textContent='Misión en cola · El equipo regresa de la planta 1';return}mission=missions.shift();p.job=mission;mission.status='Nico viene a recibir la orden';p.after=null;p.route=[];route(p,ceoReception,()=>{p.yaw=0;setMode(p,'receiving',2);announce('Nico recibe tu misión y se encarga de organizarla.')},'receive')}
function beginMeeting(){
 const p=people[0];mission.meetingStarted=false;mission.meetingAgents=[...new Set(mission.steps.slice(mission.cursor).map(s=>s.agent).filter(i=>i!==0))];
 if(!mission.meetingAgents.length){dispatch();return}
 mission.status='Nico reúne al equipo en la sala de reuniones';announce('Nico convocó a '+mission.meetingAgents.map(i=>agents[i].name).join(', ')+' a la sala de reuniones.');
 mission.meetingAgents.forEach((i,k)=>{const w=people[i];w.job=mission;w.after=null;w.timer=0;route(w,[[-2.2,0,2.2][k%3],k<3?16.5:19.5],()=>{w.yaw=k<3?0:Math.PI;setMode(w,'meeting')},'meeting-'+k)});
 route(p,[-5,15],()=>{p.yaw=0;setMode(p,'gathering')},'gather');
}
function checkMeeting(){if(!mission)return;const p=people[0];if(p.mode==='gathering'&&!mission.meetingStarted&&mission.meetingAgents.every(i=>people[i].mode==='meeting')){mission.meetingStarted=true;mission.status='Nico explica y reparte el proyecto';mission.briefingDuration=studioMeetingDuration(mission);mission.presentedCount=0;const brief='Proyecto: '+mission.text+'\nConvocados: '+mission.meetingAgents.map(i=>agents[i].name).join(', ');data.messages[0].push({text:'Reunión de equipo (simulada).\n'+brief});mission.meetingAgents.forEach(i=>data.messages[i].push({text:'Nico explicó el proyecto en la sala de reuniones.\n'+brief}));setMode(p,'briefing',mission.briefingDuration);announce('Reunión: Nico explica el objetivo, las etapas y el encargo de cada empleado.')}if(p.mode==='gatheringTask'){const step=mission.steps[mission.cursor],w=people[step.agent];if(w.mode==='supervising'&&Math.hypot(w.pos[0]-w.home[0],w.pos[1]-w.home[1])<.1){setMode(p,'delegating',2);announce('Nico confirma con '+w.name+': '+step.title+'.')}}}
function endMeeting(){announce('Reunión terminada. El equipo vuelve a sus oficinas para empezar.');mission.meetingAgents.forEach(i=>{const w=people[i];route(w,w.home,()=>{w.yaw=0;setMode(w,'supervising')},'supervise')});dispatch()}
function dispatch(){const p=people[0],step=mission.steps[mission.cursor];if(!step){route(p,p.home,()=>{p.yaw=0;mission.status='Nico revisa los resultados';setMode(p,'reviewing',3);announce('Nico está revisando la entrega del equipo.')},'review');return}if(step.agent===0){route(p,p.home,()=>{p.yaw=0;step.status='Trabajando';mission.status='Nico organiza el plan';setMode(p,'working',5)},'solo-work');return}const w=people[step.agent];w.after=null;w.route=[];w.timer=0;w.mode='supervising';w.job=mission;mission.status='Nico asigna trabajo a '+w.name;route(w,w.home,()=>{w.yaw=0;setMode(w,'supervising')},'supervise');route(p,[w.home[0]===0?1.3:w.home[0]-Math.sign(w.home[0])*1.05,w.home[1]],()=>{p.yaw=Math.sign(w.home[0])*Math.PI/2;setMode(p,'gatheringTask')},'assign')}
function delegate(){const p=people[0],s=mission.steps[mission.cursor],w=people[s.agent];s.status='Trabajando';mission.status=w.name+' está trabajando';data.messages[w.i].push({text:'Encargo de Nico: '+s.title+'\nMisión: '+mission.text+(mission.cursor>0?'\nResultados recibidos del equipo:\n'+mission.steps.slice(0,mission.cursor).map(s=>agents[s.agent].name+': '+s.output).join('\n\n'):'')});route(p,p.home,()=>{p.yaw=0;setMode(p,'supervising')},'supervise');w.route=[];w.after=null;w.pos=[...w.home];w.yaw=0;setMode(w,'working',7);announce(w.name+' trabaja en su encargo; Nico supervisa.')}
function outputFor(step){
 const base='Misión: '+mission.text;
 const outputs={
 0:'Plan del proyecto: definir objetivo, alcance, hitos y responsables.',
 1:'Requisitos: identificar usuarios, acciones principales y restricciones. Redactar historias de usuario con criterios de aceptación verificables.',
 3:'Arquitectura: separar interfaz, lógica de negocio y acceso a datos. Definir contratos entre componentes y justificar las decisiones técnicas.',
 5:'Modelo de datos: identificar entidades, claves primarias y relaciones. Revisar integridad, restricciones e índices según las consultas esperadas.',
 4:'Implementación: dividir el trabajo en funciones pequeñas, validar entradas y manejar errores. Preparar cambios a partir de los requisitos y el diseño técnico.',
 6:'Calidad: definir pruebas de casos válidos, inválidos y límites. Contrastar cada requisito con su criterio de aceptación y registrar defectos.',
 2:'Documentación: resumir objetivo, requisitos, arquitectura, datos, instalación, uso y resultados de las pruebas.'};
 const input=mission.steps.slice(0,mission.cursor).filter(x=>x.output).map(x=>agents[x.agent].name+' · '+x.title).join('; ');
 return 'Borrador de '+agents[step.agent].role.toLowerCase()+' (simulado).\n'+base+'\n\n'+outputs[step.agent]+(input?'\n\nEntradas recibidas: '+input:'')+'\n\nEsta demo propone una estructura; no genera código ejecutable, consultas verificadas ni pruebas reales.';
}
function collect(){const p=people[0],s=mission.steps[mission.cursor];s.output=outputFor(s);if(s.agent===0){s.status='Completada';mission.cursor++;dispatch();return}const w=people[s.agent];setMode(w,'handoff');mission.status='Nico recoge el trabajo de '+w.name;route(p,[w.home[0]===0?1.3:w.home[0]-Math.sign(w.home[0])*1.05,w.home[1]],()=>{p.yaw=Math.sign(w.home[0])*Math.PI/2;setMode(p,'handoff',2);announce(w.name+' comparte sus resultados con Nico.')},'handoff')}
function handoff(){const s=mission.steps[mission.cursor],w=people[s.agent];s.status='Completada';data.messages[0].push({text:w.name+' entregó: '+s.output});w.job=null;setMode(w,'idle');w.nextBreak=40;mission.cursor++;dispatch()}
function present(){const p=people[0];mission.result='Entrega simulada para: '+mission.text+'\n\n'+mission.steps.map(s=>agents[s.agent].name+' · '+s.title+'\n'+s.output).join('\n\n');mission.status='Nico viene a presentar la entrega';route(p,ceoReception,()=>{p.yaw=0;setMode(p,'waiting');mission.status='Por aceptar';data.requests.push({id:mission.id,agent:0,plan:mission.result});data.messages[0].push({text:mission.result});announce('Nico te presenta la entrega. Puedes aceptarla o pedir una revisión.');toast('Tu equipo terminó. Revisa la entrega de Nico.')},'present')}
function breakTime(p,kind,automatic=false){if(p.mode!=='idle'||p.job||p.demo||p.floor!==2)return;route(p,kind==='eating'?[10.3+p.i*.9,16.4]:[-14.8+p.i*.6,16.6],()=>{p.yaw=kind==='eating'?0:Math.PI/2;setMode(p,kind,automatic?8:12)},'break-'+kind+'-'+(automatic?8:12))}
